#[derive(Debug, Clone, Copy)]
pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: TerminalId) -> TokenKind {
    match terminal_id {
        // "a"
        TerminalId(0) => TokenKind::T0,
        // "b"
        TerminalId(1) => TokenKind::T1,
        // "c"
        TerminalId(2) => TokenKind::T2,
        // "d"
        TerminalId(3) => TokenKind::T3,
        // "e"
        TerminalId(4) => TokenKind::T4,
        // "f"
        TerminalId(5) => TokenKind::T5,
        // "g"
        TerminalId(6) => TokenKind::T6,
        // "h"
        TerminalId(7) => TokenKind::T7,
        // "i"
        TerminalId(8) => TokenKind::T8,
        // "j"
        TerminalId(9) => TokenKind::T9,
        // "k"
        TerminalId(10) => TokenKind::T10,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct ImportNamesParseTreeBuilder<'a> {
    pub arena: &'a Arena,
}
impl<'a> ImportNamesParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a Arena) -> Self {
        Self { arena: tree_arena }
    }
    fn ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        match parent {
            grammar::S => ParseTree::S(self.arena.alloc(S::Amb(alternatives))),
            grammar::PARSE => ParseTree::Parse(self.arena.alloc(Parse::Amb(alternatives))),
            grammar::PARSER => ParseTree::Parser(self.arena.alloc(Parser::Amb(alternatives))),
            grammar::SPPF_NODE => {
                ParseTree::SPPFNode(self.arena.alloc(SPPFNode::Amb(alternatives)))
            }
            grammar::INPUT => ParseTree::Input(self.arena.alloc(Input::Amb(alternatives))),
            grammar::PARSE_ERROR => {
                ParseTree::ParseError(self.arena.alloc(ParseError::Amb(alternatives)))
            }
            grammar::PARSE_SUCCESS => {
                ParseTree::ParseSuccess(self.arena.alloc(ParseSuccess::Amb(alternatives)))
            }
            grammar::GRAMMAR => ParseTree::Grammar(self.arena.alloc(Grammar::Amb(alternatives))),
            grammar::NONTERMINAL => {
                ParseTree::Nonterminal(self.arena.alloc(Nonterminal::Amb(alternatives)))
            }
            grammar::TERMINAL => ParseTree::Terminal(self.arena.alloc(Terminal::Amb(alternatives))),
            grammar::SLOT => ParseTree::Slot(self.arena.alloc(Slot::Amb(alternatives))),
            grammar::TERMINAL_SET => {
                ParseTree::TerminalSet(self.arena.alloc(TerminalSet::Amb(alternatives)))
            }
            grammar::START_S => self.start_ambiguity_node(grammar::S, alternatives),
            grammar::START_PARSE => self.start_ambiguity_node(grammar::PARSE, alternatives),
            grammar::START_PARSER => self.start_ambiguity_node(grammar::PARSER, alternatives),
            grammar::START_SPPF_NODE => self.start_ambiguity_node(grammar::SPPF_NODE, alternatives),
            grammar::START_INPUT => self.start_ambiguity_node(grammar::INPUT, alternatives),
            grammar::START_PARSE_ERROR => {
                self.start_ambiguity_node(grammar::PARSE_ERROR, alternatives)
            }
            grammar::START_PARSE_SUCCESS => {
                self.start_ambiguity_node(grammar::PARSE_SUCCESS, alternatives)
            }
            grammar::START_GRAMMAR => self.start_ambiguity_node(grammar::GRAMMAR, alternatives),
            grammar::START_NONTERMINAL => {
                self.start_ambiguity_node(grammar::NONTERMINAL, alternatives)
            }
            grammar::START_TERMINAL => self.start_ambiguity_node(grammar::TERMINAL, alternatives),
            grammar::START_SLOT => self.start_ambiguity_node(grammar::SLOT, alternatives),
            grammar::START_TERMINAL_SET => {
                self.start_ambiguity_node(grammar::TERMINAL_SET, alternatives)
            }
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
    fn start_ambiguity_node(
        &self,
        inner: NonterminalId,
        alternatives: &'a [ParseTree<'a>],
    ) -> ParseTree<'a> {
        let first = alternatives[0].unwrap_start();
        let inner_alternatives = self
            .arena
            .alloc_slice(alternatives.iter().map(|a| a.unwrap_start().node));
        ParseTree::Start(self.arena.alloc(Start {
            before: first.before,
            node: self.ambiguity_node(inner, inner_alternatives),
            after: first.after,
            span: first.span,
        }))
    }
}
impl<'a> ParseTreeBuilder<ParseTree<'a>> for ImportNamesParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &NonterminalNode,
        children: &[ParseTree<'a>],
    ) -> ParseTree<'a> {
        match nonterminal_node.return_slot {
            // S = Parse Parser SPPFNode Input ParseError ParseSuccess Grammar Nonterminal Terminal Slot
            // TerminalSet
            SlotId(11) => {
                let &[
                    parse,
                    parser,
                    sppf_node,
                    input,
                    parse_error,
                    parse_success,
                    grammar,
                    nonterminal,
                    terminal,
                    slot,
                    terminal_set,
                ] = children
                else {
                    ParseTree::unexpected_node()
                };
                ParseTree::S(self.arena.alloc(S::Alt0 {
                    parse: parse.unwrap_parse(),
                    parser: parser.unwrap_parser(),
                    sppf_node: sppf_node.unwrap_sppf_node(),
                    input: input.unwrap_input(),
                    parse_error: parse_error.unwrap_parse_error(),
                    parse_success: parse_success.unwrap_parse_success(),
                    grammar: grammar.unwrap_grammar(),
                    nonterminal: nonterminal.unwrap_nonterminal(),
                    terminal: terminal.unwrap_terminal(),
                    slot: slot.unwrap_slot(),
                    terminal_set: terminal_set.unwrap_terminal_set(),
                    span: nonterminal_node.span,
                }))
            }
            // Parse = "a"
            SlotId(13) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Parse(self.arena.alloc(Parse::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Parser = "b"
            SlotId(15) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Parser(self.arena.alloc(Parser::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // SPPFNode = "c"
            SlotId(17) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::SPPFNode(self.arena.alloc(SPPFNode::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Input = "d"
            SlotId(19) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Input(self.arena.alloc(Input::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // ParseError = "e"
            SlotId(21) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::ParseError(self.arena.alloc(ParseError::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // ParseSuccess = "f"
            SlotId(23) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::ParseSuccess(self.arena.alloc(ParseSuccess::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Grammar = "g"
            SlotId(25) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Grammar(self.arena.alloc(Grammar::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Nonterminal = "h"
            SlotId(27) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Nonterminal(self.arena.alloc(Nonterminal::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Terminal = "i"
            SlotId(29) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Terminal(self.arena.alloc(Terminal::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Slot = "j"
            SlotId(31) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Slot(self.arena.alloc(Slot::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // TerminalSet = "k"
            SlotId(33) => {
                let &[lit_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::TerminalSet(self.arena.alloc(TerminalSet::Alt0 {
                    lit_0: lit_0.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // The start nonterminals without layout
            SlotId(35) | SlotId(37) | SlotId(39) | SlotId(41) | SlotId(43) | SlotId(45)
            | SlotId(47) | SlotId(49) | SlotId(51) | SlotId(53) | SlotId(55) | SlotId(57) => {
                let &[node] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Start(self.arena.alloc(Start {
                    before: None,
                    node,
                    after: None,
                    span: nonterminal_node.span,
                }))
            }
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        self.ambiguity_node(parent, self.arena.alloc_slice(alternatives))
    }
}
// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    parser: &ImportNamesParser,
    builder: &ImportNamesParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::S => ParseTree::S(visit_sppf(root_id, parser, builder).unwrap_s()),
        grammar::PARSE => ParseTree::Parse(visit_sppf(root_id, parser, builder).unwrap_parse()),
        grammar::PARSER => ParseTree::Parser(visit_sppf(root_id, parser, builder).unwrap_parser()),
        grammar::SPPF_NODE => {
            ParseTree::SPPFNode(visit_sppf(root_id, parser, builder).unwrap_sppf_node())
        }
        grammar::INPUT => ParseTree::Input(visit_sppf(root_id, parser, builder).unwrap_input()),
        grammar::PARSE_ERROR => {
            ParseTree::ParseError(visit_sppf(root_id, parser, builder).unwrap_parse_error())
        }
        grammar::PARSE_SUCCESS => {
            ParseTree::ParseSuccess(visit_sppf(root_id, parser, builder).unwrap_parse_success())
        }
        grammar::GRAMMAR => {
            ParseTree::Grammar(visit_sppf(root_id, parser, builder).unwrap_grammar())
        }
        grammar::NONTERMINAL => {
            ParseTree::Nonterminal(visit_sppf(root_id, parser, builder).unwrap_nonterminal())
        }
        grammar::TERMINAL => {
            ParseTree::Terminal(visit_sppf(root_id, parser, builder).unwrap_terminal())
        }
        grammar::SLOT => ParseTree::Slot(visit_sppf(root_id, parser, builder).unwrap_slot()),
        grammar::TERMINAL_SET => {
            ParseTree::TerminalSet(visit_sppf(root_id, parser, builder).unwrap_terminal_set())
        }
        grammar::START_S
        | grammar::START_PARSE
        | grammar::START_PARSER
        | grammar::START_SPPF_NODE
        | grammar::START_INPUT
        | grammar::START_PARSE_ERROR
        | grammar::START_PARSE_SUCCESS
        | grammar::START_GRAMMAR
        | grammar::START_NONTERMINAL
        | grammar::START_TERMINAL
        | grammar::START_SLOT
        | grammar::START_TERMINAL_SET => {
            ParseTree::Start(visit_sppf(root_id, parser, builder).unwrap_start())
        }
        _ => panic!(),
    }
}
impl<'a> ParseTreeNode for ParseTree<'a> {
    fn child(&self, index: usize) -> Option<Self> {
        ParseTree::child(self, index)
    }
    fn child_count(&self) -> usize {
        ParseTree::child_count(self)
    }
    fn display_name(&self) -> &'static str {
        ParseTree::display_name(self)
    }
    fn span(&self) -> Span {
        ParseTree::span(self)
    }
    fn kind(&self) -> NodeKind {
        if self.is_amb() {
            NodeKind::Amb
        } else if matches!(self, ParseTree::Token(_)) {
            NodeKind::Token
        } else {
            NodeKind::Nonterminal
        }
    }
    fn node_id(&self) -> Option<usize> {
        ParseTree::node_id(self)
    }
    fn nonterminal_id(&self) -> Option<NonterminalId> {
        ParseTree::nonterminal_id(self)
    }
    fn origin(&self) -> Option<Origin> {
        ParseTree::origin(self)
    }
}
